export function manageResourceAllocation(taskComplexity, availableResources) {
  const allocation = {};
  const baseAllocation = availableResources / 2; // Reserve half for critical tasks

  allocation['reasoningDepth'] = Math.min(baseAllocation, taskComplexity * 0.6);
  allocation['realTimePerformance'] = availableResources - allocation['reasoningDepth'];

  return allocation;
}
